    function isLiveChatActiveNow() {
      try {
        var formatter = new Intl.DateTimeFormat('en-US', {
          timeZone: 'America/New_York',
          hour: 'numeric',
          hour12: false
        });
        var currentHour = parseInt(formatter.format(new Date()), 10);
        return (currentHour >= 9 && currentHour < 17);
      } catch (e) {
        return true;
      }
    }
