    function selectCourse(courseValue) {
      var valClean = (courseValue || '').toLowerCase().trim();
      valClean = valClean.replace(/&amp;/g, '&').replace(/&#x27;/g, "'");
      if (valClean.includes('alumni') || valClean.includes('clinic')) {
        var clientSession = sessionStorage.getItem('fifs_client_session');
        if (!clientSession) {
          if (typeof openAlumniAccessGateModal === 'function') openAlumniAccessGateModal();
          return;
        }
      }
      var selectElem = document.getElementById('courseSelection');
      if (selectElem) {
        var matched = false;
        for (var i = 0; i < selectElem.options.length; i++) {
          var optVal = selectElem.options[i].value.toLowerCase().trim().replace(/&amp;/g, '&');
          if (optVal === valClean) {
            selectElem.selectedIndex = i;
            selectElem.value = selectElem.options[i].value;
            matched = true;
            break;
          }
        }
        if (!matched) {
          var isVip = valClean.includes('vip') || valClean.includes('turnkey');
          for (var i = 0; i < selectElem.options.length; i++) {
            var optVal = selectElem.options[i].value.toLowerCase().trim().replace(/&amp;/g, '&');
            var optIsVip = optVal.includes('vip') || optVal.includes('turnkey');
            if (isVip === optIsVip) {
              if ((valClean.includes('renewal') || valClean.includes('8-hour') || valClean.includes('8hr')) &&
                  (optVal.includes('renewal') || optVal.includes('8-hour') || optVal.includes('8hr'))) {
                selectElem.selectedIndex = i;
                selectElem.value = selectElem.options[i].value;
                matched = true;
                break;
              } else if (valClean.includes('combo') && optVal.includes('combo')) {
                selectElem.selectedIndex = i;
                selectElem.value = selectElem.options[i].value;
                matched = true;
                break;
              } else if (valClean.includes('mastery') && optVal.includes('mastery')) {
                selectElem.selectedIndex = i;
                selectElem.value = selectElem.options[i].value;
                matched = true;
                break;
              } else if ((valClean.includes('wear & carry') || valClean.includes('ccw')) &&
                         (optVal.includes('wear & carry') || optVal.includes('ccw')) &&
                         !optVal.includes('combo') && !optVal.includes('renewal')) {
                selectElem.selectedIndex = i;
                selectElem.value = selectElem.options[i].value;
                matched = true;
                break;
              } else if (valClean.includes('hql') && optVal.includes('hql') && !optVal.includes('combo')) {
                selectElem.selectedIndex = i;
                selectElem.value = selectElem.options[i].value;
                matched = true;
                break;
              } else if (valClean.includes('coaching') && optVal.includes('coaching')) {
                selectElem.selectedIndex = i;
                selectElem.value = selectElem.options[i].value;
                matched = true;
                break;
              } else if (valClean.includes('cleaning') && optVal.includes('cleaning')) {
                selectElem.selectedIndex = i;
                selectElem.value = selectElem.options[i].value;
                matched = true;
                break;
              } else if (valClean.includes('children') && optVal.includes('children')) {
                selectElem.selectedIndex = i;
                selectElem.value = selectElem.options[i].value;
                matched = true;
                break;
              } else if (valClean.includes('alumni') && optVal.includes('alumni')) {
                selectElem.selectedIndex = i;
                selectElem.value = selectElem.options[i].value;
                matched = true;
                break;
              }
            }
          }
        }
        if (typeof updateFormPriceDisplay === 'function') {
          updateFormPriceDisplay();
        }
      }
      if (typeof openCourseBookingModal === 'function') {
        openCourseBookingModal();
      }
    }
    window.selectCourse = selectCourse;
