    function generateCoachWadeReply(name, msg) {
      var m = (msg || '').toLowerCase();
      if (m.includes('schedule') || m.includes('date') || m.includes('when') || m.includes('calendar') || m.includes('day')) {
        return "We hold our live-fire group sessions at <strong>Cindy\'s Hot Shots</strong> in Glen Burnie on <strong>Saturdays and Sundays at 9:00 AM</strong>. If you enroll in our 👑 <strong>VIP Turnkey</strong> track, you unlock priority 7-day flexible scheduling (Monday through Sunday anytime). Would you like to check available dates?";
      }
      if (m.includes('price') || m.includes('cost') || m.includes('fee') || m.includes('tuition') || m.includes('how much')) {
        return "Our pricing is 100% transparent with zero hidden fees:<br>• <strong>Maryland CCW & HQL Combo:</strong> $229.99 Base / $374.99 VIP Turnkey<br>• <strong>Wear & Carry (16-Hr Initial):</strong> $199.99 Base / $324.99 VIP<br>• <strong>Wear & Carry (8-Hr Renewal):</strong> $174.99 Base (10% off with promo code <code>RENEWAL10</code>)<br>• <strong>Maryland HQL:</strong> $100 Base / $164.99 VIP<br>• <strong>1-on-1 Private Range Coaching:</strong> $124.99/hr Base / $194.99/hr VIP";
      }
      if (m.includes('where') || m.includes('location') || m.includes('range') || m.includes('address') || m.includes('cindy')) {
        return "All our practical live-fire range qualifications take place at <strong>Cindy\'s Hot Shots</strong>, located at <strong>114.99 Holsum Way, Glen Burnie, MD 21060</strong>. It\'s a premier, state-of-the-art indoor climate-controlled range.";
      }
      if (m.includes('ammo') || m.includes('ammunition') || m.includes('round') || m.includes('caliber')) {
        return "You\'ll need <strong>4.990 to 100 rounds</strong> of clean factory target brass ammunition (9mm, .380, etc.). It\'s available on-site at Cindy\'s Hot Shots or included in our VIP Turnkey package. <em>Mandatory safety rule:</em> strictly zero live ammo in the classroom—keep it locked in your trunk until range live-fire!";
      }
      if (m.includes('hql') || m.includes('wear and carry') || m.includes('ccw') || m.includes('permit') || m.includes('difference')) {
        return "An <strong>HQL</strong> is required by Maryland law just to purchase or rent a handgun. A <strong>Wear & Carry Permit (CCW)</strong> authorizes legal concealed carry in public. Our <strong>Combo course</strong> gives you both in one weekend and saves you $100 under Maryland Public Safety § 4.99-117.1!";
      }
      return "Thank you for your message, " + escapeHtml(name) + "! I\'ve received your note on my direct mobile line ((443) 990-1304). If I am currently coaching on the firing line, I will call or text you back promptly. Feel free to ask any other questions or call me directly anytime!";
    }
